import json
h,w=29,23
g=[[1]*w for _ in range(h)]
# retain all original 3 pixels
for c in list(range(10,19))+[20,21]: g[13][c]=3
for r in range(14,23):
    g[r][10]=g[r][21]=3
    if r in (14,16,17): g[r][13]=3
for c in range(10,22): g[23][c]=3
# Connect same-color anchors along each row and column with 2, without overwriting 3.
for r in range(h):
    cs=[c for c,v in enumerate(g[r]) if v==3]
    if len(cs)>=2:
        for c in range(cs[0],cs[-1]+1):
            if g[r][c]==1: g[r][c]=2
for c in range(w):
    rs=[r for r in range(h) if g[r][c]==3]
    if len(rs)>=2:
        for r in range(rs[0],rs[-1]+1):
            if g[r][c]==1: g[r][c]=2
assert len(g)==29 and all(len(row)==23 for row in g)
print(json.dumps({'action':'submit','grid':g},separators=(',',':')))

